class MassCompanySeederService
{
    /**
     * Seed 50 realistic companies across different industries,
     * each with at least 10 realistic job postings (Total 500+ jobs).
     */
    public static function seed50Companies(): array
    {
        $passwordHash = Hash::make('password123');
        $companiesData = self::getCompaniesDefinition();

        $seededCompaniesCount = 0;
        $seededJobsCount = 0;
        $credentialsList = [];

        try {
            DB::statement('SET FOREIGN_KEY_CHECKS=0;');

            foreach ($companiesData as $companyDef) {
                // 1. Create or Find User
                $user = User::firstOrCreate(
                    ['email' => $companyDef['email']],
                    [
                        'name' => $companyDef['company_name'],
                        'password' => $passwordHash,
                        'role' => 'company',
                        'email_verified_at' => now(),
                        'account_status' => 'active',
                    ]
                );

                // 2. Create or Find Company Profile
                $company = Company::firstOrCreate(
                    ['user_id' => $user->id],
                    [
                        'name' => $companyDef['company_name'],
                        'industry' => $companyDef['industry'],
                        'description' => $companyDef['description'],
                        'location' => $companyDef['location'],
                        'website' => $companyDef['website'],
                        'company_size' => $companyDef['company_size'],
                        'founded_year' => $companyDef['founded_year'],
                        'verification_status' => 'verified',
                        'contact_email' => $companyDef['email'],
                        'dark_mode' => false,
                        'notify_messages' => true,
                        'notify_candidate_activity' => true,
                        'notify_quiz_results' => true,
                        'notify_post_activity' => true,
                    ]
                );

                $seededCompaniesCount++;

                $credentialsList[] = [
                    'id' => $company->id,
                    'company_name' => $companyDef['company_name'],
                    'industry' => $companyDef['industry'],
                    'email' => $companyDef['email'],
                    'password' => 'password123',
                    'jobs_count' => count($companyDef['jobs']),
                ];

                // 3. Create at least 10 jobs for this company
                foreach ($companyDef['jobs'] as $jobDef) {
                    JobPosting::firstOrCreate(
                        [
                            'company_id' => $company->id,
                            'title' => $jobDef['title'],
                        ],
                        [
                            'description' => $jobDef['description'],
                            'required_skills' => $jobDef['required_skills'],
                            'job_type' => $jobDef['job_type'] ?? 'full_time',
                            'work_mode' => $jobDef['work_mode'] ?? 'remote',
                            'experience_level' => $jobDef['experience_level'] ?? 'mid',
                            'location' => $companyDef['location'],
                            'salary_min' => $jobDef['salary_min'] ?? 60000,
                            'salary_max' => $jobDef['salary_max'] ?? 110000,
                            'salary_currency' => 'USD',
                            'application_deadline' => now()->addDays(rand(30, 90)),
                            'status' => 'active',
                        ]
                    );
                    $seededJobsCount++;
                }
            }

            DB::statement('SET FOREIGN_KEY_CHECKS=1;');

            return [
                'status' => 'success',
                'message' => "Successfully seeded {$seededCompaniesCount} companies and {$seededJobsCount} jobs.",
                'total_companies' => $seededCompaniesCount,
                'total_jobs' => $seededJobsCount,
                'credentials' => $credentialsList,
            ];

        } catch (\Throwable $e) {
            DB::statement('SET FOREIGN_KEY_CHECKS=1;');
            Log::error('Mass company seeding error: ' . $e->getMessage());
            return [
                'status' => 'error',
                'message' => $e->getMessage(),
            ];
        }
    }

